python3 -c "
import json
with open('EnumTest.flow') as f:
    flow=json.load(f)
for d in flow.get('definitions',[]):
    if 'gmail' in d.get('nodeType','').lower():
        ctx=d.get('model',{}).get('context',[])
        for c in ctx:
            if c.get('name')=='objectName':
                print('objectName:',c.get('value'))
        # also check form
        form=d.get('form',{})
        sections=form.get('sections',[])
        for s in sections:
            for field in s.get('fields',[]):
                cp=field.get('componentProps',{})
                cd=cp.get('connectorDetail',{})
                conf_str=cd.get('configuration','')
                if conf_str:
                    try:
                        conf=json.loads(conf_str)
                        print('activityType:', conf.get('activityType'))
                        print('objectName in config:', conf.get('objectName'))
                    except: pass
" 2>/dev/null

